import 'dart:async';
import 'package:flutter/material.dart';
import '../services/api.dart';
import 'call_screen.dart';
class ChatScreen extends StatefulWidget{final int conversationId;final Map other;const ChatScreen({super.key,required this.conversationId,required this.other});@override State<ChatScreen>createState()=>_ChatScreenState();}
class _ChatScreenState extends State<ChatScreen>{List messages=[];final text=TextEditingController();Timer? timer;@override void initState(){super.initState();load();timer=Timer.periodic(const Duration(seconds:2),(_)=>load(silent:true));}@override void dispose(){timer?.cancel();text.dispose();super.dispose();}Future<void>load({bool silent=false})async{try{final j=await Api.request('/messages/${widget.conversationId}');if(mounted)setState(()=>messages=List.from(j['messages']??[]));}catch(_){}}Future<void>send()async{final s=text.text.trim();if(s.isEmpty)return;text.clear();await Api.request('/messages/send',method:'POST',body:{'conversation_id':widget.conversationId,'body':s});await load();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.other['name']??'مستخدم'),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>CallScreen(other:Map<String,dynamic>.from(widget.other)))),icon:const Icon(Icons.videocam))]),body:Column(children:[Expanded(child:ListView.builder(padding:const EdgeInsets.all(12),itemCount:messages.length,itemBuilder:(_,i){final m=Map<String,dynamic>.from(messages[i]);final incoming=m['sender_id'].toString()==widget.other['id'].toString();return Align(alignment:incoming?Alignment.centerLeft:Alignment.centerRight,child:Container(margin:const EdgeInsets.symmetric(vertical:4),padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),constraints:const BoxConstraints(maxWidth:280),decoration:BoxDecoration(color:incoming?const Color(0xff202027):const Color(0xfffe2c55),borderRadius:BorderRadius.circular(18)),child:Text(m['body']??'')));})),SafeArea(child:Padding(padding:const EdgeInsets.all(8),child:Row(children:[Expanded(child:TextField(controller:text,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'اكتب رسالة...'))),const SizedBox(width:8),IconButton.filled(onPressed:send,icon:const Icon(Icons.send))])))]));}
